insert into public.books (title,author,description,cover_url,pages,tags,chapters,quotes) values
('عائد إلى حيفا','غسان كنفاني','رواية عن الذاكرة والاقتلاع والعودة.','https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600',96,array['رواية','فلسطين'],'["الطريق إلى حيفا","في البيت القديم","المواجهة"]','{"أتعرفين ما هو الوطن يا صفية؟ الوطن هو ألا يحدث ذلك كله."}'),
('الأيام','طه حسين','سيرة أدبية عن العلم والإرادة.','https://images.unsplash.com/photo-1512820790803-83ca734da794?w=600',320,array['سيرة','كلاسيكيات'],'["في القرية","في الأزهر","في الجامعة"]','{"العلم لا يعطيك بعضه حتى تعطيه كلك."}'),
('موسم الهجرة إلى الشمال','الطيب صالح','رحلة بين ضفتي النيل والغرب.','https://images.unsplash.com/photo-1495446815901-a7297e633e8d?w=600',184,array['رواية','عالمية'],'["موسم العودة","مصطفى سعيد","القرية"]','{"إنني أسمع صوت الماء في النهر، كأنه يناديني."}'),
('رجال في الشمس','غسان كنفاني','حكاية البحث عن حياة أفضل.','https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=600',80,array['رواية','فلسطين'],'["أبو قيس","أسعد","مروان"]','{"لماذا لم تدقوا جدران الخزان؟"}'),
('حي بن يقظان','ابن طفيل','حكاية فلسفية عن المعرفة والفطرة.','https://images.unsplash.com/photo-1521587760476-6c12a4b040da?w=600',112,array['فلسفة','تراث'],'["الجزيرة","المعرفة","الحقيقة"]','{"كلما اتسعت الرؤية ضاقت العبارة."}'),
('النبي','جبران خليل جبران','تأملات في الحب والعمل والحرية.','https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=600',128,array['شعر','تأملات'],'["الحب","العمل","الحرية"]','{"الحب لا يعطي إلا ذاته ولا يأخذ إلا من ذاته."}'),
('الخبز الحافي','محمد شكري','سيرة ذاتية أدبية صادمة.','https://images.unsplash.com/photo-1511108690759-009c86a2f47f?w=600',240,array['سيرة'],'["الطفولة","المدينة","الطريق"]','{"الكتابة شكل من أشكال المقاومة."}'),
('مدن الملح','عبد الرحمن منيف','ملحمة التحول الاجتماعي والاقتصادي.','https://images.unsplash.com/photo-1495640388908-05fa85288e61?w=600',510,array['رواية','تاريخ'],'["التيه","الأخدود","تقاسيم الليل"]','{"المدن لا تموت، لكنها تتغير."}'),
('في مديح الحب','علي شريعتي','تأملات إنسانية وروحية.','https://images.unsplash.com/photo-1516979187457-637abb4f9353?w=600',144,array['فكر','تأملات'],'["المعنى","الاختيار","الحرية"]','{"الإنسان مشروع لا يكتمل."}'),
('قنديل أم هاشم','يحيى حقي','صراع الأصالة والحداثة في الحارة المصرية.','https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=600',104,array['رواية','كلاسيكيات'],'["العودة","القنديل","الاختيار"]','{"ليس كل ما نراه حقيقة."}'),
('رسائل الأحزان','مصطفى صادق الرافعي','نثر عربي وجداني رفيع.','https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=600',176,array['أدب','كلاسيكيات'],'["الحزن","الذكرى","الأمل"]','{"الحزن يعلّم القلب لغة لا يعرفها الفرح."}'),
('ساق البامبو','سعود السنعوسي','هوية عالقة بين ثقافتين.','https://images.unsplash.com/photo-1519681393784-d120267933ba?w=600',396,array['رواية','هوية'],'["البداية","الاسم","الوطن"]','{"الوطن ليس مكانًا فقط، بل اعتراف أيضًا."}');
